'use strict';
window.DashboardOverview=(()=>{
 let shownMonth='';
 function model(){const c=state.curriculum,d=window.StudyHub.progressData(),parts=d.student.reduce((sum,ch)=>sum+ch.parts,0),total=d.student.length*d.parts;return{hanja:{done:d.hanja,total:window.StudyHub.getChapters().length},student:{done:parts,total,chapters:d.student.filter(ch=>ch.parts===d.parts).length},streak:window.StudyEngine.streak(c.sessions,today(),c.restDays)}}
 function chart(key,title,done,total,detail){const percent=total?Math.round(done/total*100):0,exact=total?done/total*100:0;return`<button class="completion-card ${key}" data-overview-book="${key}" aria-label="${e(title)}: ${percent}% completed. ${e(detail)}. Open chapter progress."><span class="completion-title">${e(title)}</span><svg class="completion-ring" viewBox="0 0 120 120" role="img" aria-label="${percent}% completed"><circle class="ring-track" cx="60" cy="60" r="46" pathLength="100"/><circle class="ring-fill" cx="60" cy="60" r="46" pathLength="100" stroke-dasharray="${exact} 100" transform="rotate(-90 60 60)"/><text x="60" y="64" text-anchor="middle">${percent}%</text><text class="ring-caption" x="60" y="80" text-anchor="middle">COMPLETE</text></svg><strong>${e(detail)}</strong></button>`}
 function calendarHTML(){const c=state.curriculum,first=new Date(shownMonth+'-01T12:00:00Z'),offset=(first.getUTCDay()+6)%7,days=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate(),label=first.toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'});return`<section class="mini-calendar" aria-label="Study calendar"><div class="mini-calendar-head"><h3>${label}</h3><div><button id="miniMonthPrev" aria-label="Previous calendar month">‹</button><button id="miniMonthNext" aria-label="Next calendar month">›</button></div></div><div class="mini-calendar-grid">${['M','T','W','T','F','S','S'].map(d=>`<span class="mini-weekday">${d}</span>`).join('')}${'<span aria-hidden="true"></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const day=shownMonth+'-'+String(i+1).padStart(2,'0'),studied=!!c.sessions[day]?.minutes,planned=!!c.calendar[day]?.note;return`<button data-mini-date="${day}" class="mini-day ${day===today()?'is-today':''} ${studied?'is-studied':''} ${planned?'is-planned':''} ${c.restDays?.[day]?'is-rest':''}" ${day===today()?'aria-current="date"':''} aria-label="${day}${studied?', studied '+c.sessions[day].minutes+' minutes':''}${planned?', planned':''}${c.restDays?.[day]?', rest day, streak protected':''}">${i+1}${c.restDays?.[day]?'<small aria-hidden="true">❄</small>':''}</button>`}).join('')}</div><div class="mini-calendar-footer"><span><i></i> Studied</span><span>❄ Rest day</span><button id="miniCalendarToday">Today</button><button id="miniCalendarOpen">Open calendar ↗</button></div></section>`}
 function changeMonth(n){const date=new Date(shownMonth+'-01T12:00:00Z');date.setUTCMonth(date.getUTCMonth()+n);shownMonth=date.toISOString().slice(0,7);render()}
 function render(){const box=$('#dashboardOverview');if(!box||!state.curriculum||!window.StudyHub.getChapters().length)return;shownMonth||=today().slice(0,7);const d=model(),vocab=words.filter(w=>!w.hanjaRef&&w.studyRef?.kind!=='grammar'),known=vocab.filter(learned).length;box.innerHTML=`<div class="book-completion-grid">${chart('hanja','Hanja book',d.hanja.done,d.hanja.total,`${d.hanja.done} / ${d.hanja.total} chapters`)}${chart('student','Korean Made Easy',d.student.done,d.student.total,`${d.student.done} / ${d.student.total} parts · ${d.student.chapters} / 15 chapters`)}${calendarHTML()}</div><div class="overview-summary"><span><strong>${d.streak.current}</strong> day streak</span><span><strong>${known}</strong> / ${vocab.length} vocabulary learned</span><span class="weekly-freeze-status">${window.StudyEngine.weeklyRest(state.curriculum,today()).date?'❄ Weekly rest used':'❄ 1 weekly rest available'}</span><button id="overviewProgress">View all progress →</button></div>`;document.querySelectorAll('[data-overview-book]').forEach(b=>b.onclick=()=>{window.StudyHub.open('progress');$('#stackTitle').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-mini-date]').forEach(b=>b.onclick=()=>window.StudyHub.openDay(b.dataset.miniDate));$('#miniMonthPrev').onclick=()=>changeMonth(-1);$('#miniMonthNext').onclick=()=>changeMonth(1);$('#miniCalendarToday').onclick=()=>{shownMonth=today().slice(0,7);render()};$('#miniCalendarOpen').onclick=()=>window.StudyHub.openDay(today());$('#overviewProgress').onclick=()=>{window.StudyHub.open('progress');$('#stackTitle').scrollIntoView({behavior:'smooth',block:'start'})}}
 return{render,model};
})();
